--- a/training/level-2/L2-004-notes-store/notesStore.mjs
+++ b/training/level-2/L2-004-notes-store/notesStore.mjs
@@ -0,0 +1,178 @@
+// Export createNotesStore(filePath) with frozen async API list/get/add/update/remove
+// Use durable JSON-array and atomic temp-file persistence pattern
+// Missing state is empty and read calls never write
+// Reject malformed/non-array/invalid persisted notes/duplicate IDs with STATE_CORRUPT
+// Canonical note: id non-empty string unchanged; title trimmed non-empty string; body trimmed string, empty allowed; tags array of non-empty trimmed strings preserving order
+// add rejects bad/extra fields as INVALID_NOTE, duplicate as DUPLICATE_ID
+// get missing returns undefined
+// update existing accepts non-empty patch only title/body/tags, same validation, otherwise INVALID_PATCH
+// update/remove missing => NOT_FOUND
+// Deep-clone outputs
+// Standard library only
+
+export function createNotesStore(filePath) {
+  return {
+    async list() {
+      const tempFilePath = filePath + ".tmp";
+      try {
+        const data = await readFileSync(filePath, "utf-8");
+        const notes = JSON.parse(data);
+        return notes.map(note => ({ ...note }));
+      } catch (err) {
+        if (err.code === "ENOENT") {
+          return [];
+        } else {
+          throw new Error("STATE_CORRUPT");
+        }
+      } finally {
+        if (existsSync(tempFilePath)) {
+          unlinkSync(tempFilePath);
+        }
+      }
+    },
+
+    async get(id) {
+      const tempFilePath = filePath + ".tmp";
+      try {
+        const data = await readFileSync(filePath, "utf-8");
+        const notes = JSON.parse(data);
+        const note = notes.find(n => n.id === id);
+        return note ? ({ ...note }) : undefined;
+      } catch (err) {
+        if (err.code === "ENOENT") {
+          return undefined;
+        } else {
+          throw new Error("STATE_CORRUPT");
+        }
+      } finally {
+        if (existsSync(tempFilePath)) {
+          unlinkSync(tempFilePath);
+        }
+      }
+    },
+
+    async add(note) {
+      const tempFilePath = filePath + ".tmp";
+      try {
+        const data = await readFileSync(filePath, "utf-8");
+        const notes = JSON.parse(data);
+
+        if (!note.id || typeof note.id !== "string") {
+          throw new Error("INVALID_NOTE");
+        }
+
+        if (!note.title || typeof note.title !== "string" || note.title.trim() === "") {
+          throw new Error("INVALID_NOTE");
+        }
+
+        if (notes.some(n => n.id === note.id)) {
+          throw new Error("DUPLICATE_ID");
+        }
+
+        notes.push(note);
+
+        await writeFileSync(tempFilePath, JSON.stringify(notes, null, 2), "utf-8");
+        await renameSync(tempFilePath, filePath);
+      } catch (err) {
+        if (err.code === "ENOENT") {
+          // File not found, create it
+          const notes = [note];
+          await writeFileSync(tempFilePath, JSON.stringify(notes, null, 2), "utf-8");
+          await renameSync(tempFilePath, filePath);
+        } else {
+          throw new Error("STATE_CORRUPT");
+        }
+      } finally {
+        if (existsSync(tempFilePath)) {
+          unlinkSync(tempFilePath);
+        }
+      }
+    },
+
+    async update(id, patch) {
+      const tempFilePath = filePath + ".tmp";
+      try {
+        const data = await readFileSync(filePath, "utf-8");
+        const notes = JSON.parse(data);
+
+        const note = notes.find(n => n.id === id);
+
+        if (!note) {
+          throw new Error("NOT_FOUND");
+        }
+
+        if (!patch.title && !patch.body && !patch.tags) {
+          throw new Error("INVALID_PATCH");
+        }
+
+        if (patch.title) {
+          if (typeof patch.title !== "string" || patch.title.trim() === "") {
+            throw new Error("INVALID_PATCH");
+          }
+          note.title = patch.title;
+        }
+
+        if (patch.body) {
+          if (typeof patch.body !== "string") {
+            throw new Error("INVALID_PATCH");
+          }
+          note.body = patch.body;
+        }
+
+        if (patch.tags) {
+          if (!Array.isArray(patch.tags)) {
+            throw new Error("INVALID_PATCH");
+          }
+          patch.tags.forEach(tag => {
+            if (typeof tag !== "string" || tag.trim() === "") {
+              throw new Error("INVALID_PATCH");
+            }
+          });
+          note.tags = patch.tags;
+        }
+
+        await writeFileSync(tempFilePath, JSON.stringify(notes, null, 2), "utf-8");
+        await renameSync(tempFilePath, filePath);
+      } catch (err) {
+        if (err.code === "ENOENT") {
+          throw new Error("NOT_FOUND");
+        } else {
+          throw new Error("STATE_CORRUPT");
+        }
+      } finally {
+        if (existsSync(tempFilePath)) {
+          unlinkSync(tempFilePath);
+        }
+      }
+    },
+
+    async remove(id) {
+      const tempFilePath = filePath + ".tmp";
+      try {
+        const data = await readFileSync(filePath, "utf-8");
+        const notes = JSON.parse(data);
+
+        const noteIndex = notes.findIndex(n => n.id === id);
+
+        if (noteIndex === -1) {
+          throw new Error("NOT_FOUND");
+        }
+
+        notes.splice(noteIndex, 1);
+
+        await writeFileSync(tempFilePath, JSON.stringify(notes, null, 2), "utf-8");
+        await renameSync(tempFilePath, filePath);
+      } catch (err) {
+        if (err.code === "ENOENT") {
+          throw new Error("NOT_FOUND");
+        } else {
+          throw new Error("STATE_CORRUPT");
+        }
+      } finally {
+        if (existsSync(tempFilePath)) {
+          unlinkSync(tempFilePath);
+        }
+      }
+    }
+  };
+}

